package com.portfolio.assetory.refund;
import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface RefundRepository extends JpaRepository<Refund,Long>{boolean existsByOrderItemId(Long orderItemId);@Query("select r from Refund r join fetch r.orderItem i join fetch i.order o join fetch i.product where r.id=:id and o.buyer.id=:buyer")Optional<Refund> findForBuyer(@Param("id")Long id,@Param("buyer")Long buyer);@Query("select r from Refund r join fetch r.orderItem i join fetch i.order o join fetch i.product where r.id=:id and o.seller.id=:seller")Optional<Refund> findForSeller(@Param("id")Long id,@Param("seller")Long seller);@Query(value="select r from Refund r join fetch r.orderItem i join fetch i.order o join fetch i.product where o.buyer.id=:buyer",countQuery="select count(r) from Refund r join r.orderItem i join i.order o where o.buyer.id=:buyer")org.springframework.data.domain.Page<Refund> findAllForBuyer(@Param("buyer")Long buyer,org.springframework.data.domain.Pageable pageable);@Query(value="select r from Refund r join fetch r.orderItem i join fetch i.order o join fetch i.product where o.seller.id=:seller",countQuery="select count(r) from Refund r join r.orderItem i join i.order o where o.seller.id=:seller")org.springframework.data.domain.Page<Refund> findAllForSeller(@Param("seller")Long seller,org.springframework.data.domain.Pageable pageable);}
